import {adapters,numeric,splitList,safeLink,validateConfig,filterJobs,viewLabels,resolveView} from './lib.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const clone=v=>JSON.parse(JSON.stringify(v));
const STORAGE='jobradar.config.v1';
const state={jobs:[],config:null,original:null,runs:[],demo:false,page:1,filters:{query:'',location:'',workplaces:[],sources:[],status:'active',sort:'newest'}};
const labels=viewLabels;
const statusLabels={cached:'沿用近期数据',ok:'已完成',partial:'部分完成',error:'采集失败',blocked:'访问受限',disabled:'未启用',pending:'等待采集',stale:'待复核',active:'可关注',expired:'已过期',demo:'示例预览'};
const workLabels={remote:'远程办公',hybrid:'混合办公',onsite:'现场办公',unknown:'方式未注明'};
let editing=null, toastTimer, currentView='home';
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function datetime(value){return value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'未注明';}
function relative(value){if(!value)return'发布日期未知';const days=Math.max(0,Math.floor((Date.now()-Date.parse(value))/86400000));return days===0?'今天':days===1?'昨天':`${days} 天前`;}
function badge(status){return node('span',`status-badge ${status}`,statusLabels[status]||status);}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json;charset=utf-8'}));const a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function navigate(){const name=resolveView(location.hash,currentView);const changed=name!==currentView;currentView=name;document.body.classList.toggle('home-mode',name==='home');$$('.view').forEach(n=>n.hidden=n.id!==`view-${name}`);$$('[data-view]').forEach(n=>{n.classList.toggle('active',n.dataset.view===name);if(n.dataset.view===name)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});$('#breadcrumb').textContent=labels[name];document.title=`${state.config?.project.name||'工作雷达'} · ${labels[name]}`;if(changed){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}}
function savedDraft(){try{return JSON.parse(localStorage.getItem(STORAGE)||'null');}catch{return null;}}
function saveDraft(config){validateConfig(config);try{localStorage.setItem(STORAGE,JSON.stringify(config));}catch{toast('浏览器无法保存草稿，请立即导出配置。');}state.config=clone(config);$('#draft-banner').hidden=false;renderConfig();renderSources();renderStats();toast('已保存本地草稿；导出到仓库后，自动采集才会采用。');}
async function readData(file){const response=await fetch(new URL(`./data/${file}`,import.meta.url),{cache:'no-store'});if(!response.ok)throw new Error(`读取 ${file} 失败（${response.status}）`);return response.json();}
async function load(){
 $('#reload').disabled=true;
 try{const[data,config,runs]=await Promise.all([readData('jobs.json'),readData('config.json'),readData('runs.json')]);validateConfig(config);if(data.schema_version!==1||!Array.isArray(data.jobs))throw new Error('岗位数据格式无效');state.original=clone(config);let draft=savedDraft();if(draft){try{validateConfig(draft);}catch{draft=null;toast('保存的草稿格式无效，已读取仓库配置。');}}state.config=draft||config;state.jobs=data.jobs;state.demo=data.demo;state.runs=runs;$('#demo-banner').hidden=!data.demo;$('#draft-banner').hidden=!draft;$('#data-label').textContent=data.demo?'示例数据 · 自动化未启用':'静态数据快照';$('#updated-at').textContent=`数据生成于 ${datetime(data.generated_at)}`;$('#load-error').hidden=true;renderStats();renderHome(data);renderFilters();renderJobs();renderConfig();renderSources();renderRuns();navigate();registerAgentTools();}
 catch(error){$('#load-error').hidden=false;$('#load-error').textContent=`无法载入站点数据：${error.message}。请先运行本地构建，再通过 HTTP 服务打开站点。`;$('#result-count').textContent='数据未加载';$('#home-job-count').textContent='—';$('#home-source-count').textContent='—';$('#home-source-names').replaceChildren(node('span','','数据暂不可用'));$('#home-updated').textContent='请稍后刷新页面重试';}
 finally{$('#reload').disabled=false;}
}
function renderStats(){$('#nav-count').textContent=state.jobs.length;$('#stat-total').textContent=state.jobs.length;$('#stat-active').textContent=state.jobs.filter(j=>j.status==='active').length;$('#stat-remote').textContent=state.jobs.filter(j=>j.workplace==='remote'&&j.status==='active').length;$('#stat-sources').textContent=state.config.sources.length;$('#stat-enabled').textContent=`${state.config.sources.filter(s=>s.enabled).length} 个已启用`;}
function renderHome(data){
 const names=[...new Set(data.jobs.map(job=>job.source_name))];
 $('#home-data-caption').textContent=data.demo?'示例岗位快照':'当前岗位快照';
 $('#home-job-count').textContent=data.jobs.length;
 $('#home-source-count').textContent=names.length;
 $('#home-source-names').replaceChildren(...(names.length?names:['暂无已收录来源']).map(name=>node('span','',name)));
 $('#home-updated').textContent=`数据更新于 ${datetime(data.generated_at)}`;
}
function renderFilters(){const location=$('#location');location.replaceChildren(node('option','','全部地点'));location.firstChild.value='';[...new Set(state.jobs.map(j=>j.location))].sort().forEach(v=>{const o=node('option','',v);o.value=v;location.append(o);});if(![...location.options].some(o=>o.value===state.filters.location))state.filters.location='';location.value=state.filters.location;const group=$('#source-filters');group.replaceChildren(node('legend','','招聘来源'));state.config.sources.forEach(s=>{const count=state.jobs.filter(j=>(j.source_ids||[j.source_id]).includes(s.id)).length;const label=node('label','check');const input=node('input');input.type='checkbox';input.name='source';input.value=s.id;input.checked=state.filters.sources.includes(s.id);input.addEventListener('change',applyFilters);label.append(input,document.createTextNode(s.name),node('span','',count));group.append(label);});$('#remote-count').textContent=state.jobs.filter(j=>j.workplace==='remote').length;}
function applyFilters(){state.filters={query:$('#search').value,location:$('#location').value,workplaces:$$('[name=workplace]:checked').map(x=>x.value),sources:$$('[name=source]:checked').map(x=>x.value),status:$('#status').value,sort:$('#sort').value};state.page=1;renderJobs();}
function resetFilters(){state.filters={query:'',location:'',workplaces:[],sources:[],status:'all',sort:'newest'};$('#search').value='';$('#location').value='';$('#status').value='all';$('#sort').value='newest';$$('[name=workplace],[name=source]').forEach(x=>x.checked=false);state.page=1;renderJobs();}
function renderJobs(){const results=filterJobs(state.jobs,state.filters);const pages=Math.max(1,Math.ceil(results.length/8));state.page=Math.min(state.page,pages);$('#result-count').textContent=`找到 ${results.length} 个岗位`;$('#result-note').textContent=state.demo?'示例数据':'';$('#empty').hidden=!!results.length;const grid=$('#job-grid');grid.replaceChildren();results.slice((state.page-1)*8,state.page*8).forEach((job,i)=>{
 const card=node('article','job-card');const company=node('div','company-line');const logo=node('span',`company-logo tone-${i%4}`,job.company.slice(0,1));logo.setAttribute('aria-hidden','true');const name=node('div');name.append(node('div','company-name',job.company),node('small','',job.employment_type||'类型未注明'));company.append(logo,name,node('span','source-pill',job.source_name));const title=node('button','job-title',job.title);title.addEventListener('click',()=>showJob(job));const salary=node('div',`salary${job.salary?'':' unspecified'}`,job.salary||'薪资未公开');const meta=node('div','job-meta',`${job.location} · ${workLabels[job.workplace]||workLabels.unknown}`);const tags=node('div','tags');job.tags.slice(0,4).forEach(t=>tags.append(node('span','tag',t)));const foot=node('div','job-footer');foot.append(node('span','',job.status==='active'?`${relative(job.first_seen_at)}收录`:statusLabels[job.status]));const detail=node('button','detail-button','查看详情 ↗');detail.setAttribute('aria-label',`查看 ${job.title} 详情`);detail.addEventListener('click',()=>showJob(job));foot.append(detail);card.append(company,title,salary,meta,tags,foot);grid.append(card);
 });$('#page-info').textContent=results.length?`第 ${state.page} / ${pages} 页 · 每页 8 个岗位`:'暂无岗位';$('#prev-page').disabled=state.page<=1;$('#next-page').disabled=state.page>=pages;}
function showJob(job){const container=$('#job-detail');container.replaceChildren();container.append(node('div','muted',job.company),node('h2','detail-title',job.title),node('div','salary',job.salary||'薪资未公开'),node('div','job-meta',`${job.location} · ${workLabels[job.workplace]||workLabels.unknown} · ${job.employment_type||'类型未注明'}`));const tags=node('div','tags');job.tags.forEach(t=>tags.append(node('span','tag',t)));container.append(tags,badge(job.status));if(job.demo)container.append(node('div','notice','此岗位为虚构示例，不支持投递。'));container.append(node('div','detail-description',job.description||'来源未提供岗位描述，请查看职位原文。'));const provenance=node('div','detail-provenance');provenance.append(node('div','',`来源：${job.source_name} · 发布：${job.published_at?datetime(job.published_at):'日期未知'}`),node('div','',`首次收录：${datetime(job.first_seen_at)}`),node('div','',`最近核验：${datetime(job.last_seen_at)}`));if(job.updated_at)provenance.append(node('div','',`原文更新：${datetime(job.updated_at)}`));container.append(provenance);const href=safeLink(job.url);if(!job.demo&&href){const a=node('a','button primary','查看职位原文 ↗');a.href=href;a.target='_blank';a.rel='noopener noreferrer';container.append(a);}$('#job-dialog').showModal();}
function renderSources(){const grid=$('#source-grid');grid.replaceChildren();state.config.sources.forEach((s,i)=>{const card=node('article','source-card');const top=node('div','source-card-top');top.append(node('span',`company-logo tone-${i%4}`,s.name.slice(0,1)),badge(s.enabled?(state.runs[0]?.sources.find(o=>o.source_id===s.id)?.status||'pending'):'disabled'));card.append(top,node('h2','',s.name),node('span','source-kind',adapters[s.adapter]),node('p','',s.notes||'使用默认策略检索公开岗位。'));const foot=node('div','source-foot');foot.append(node('span','',Object.keys(s.strategy||{}).length?`${Object.keys(s.strategy).length} 项专属策略`:'继承默认策略'));const button=node('button','text-button','配置来源 ↗');button.addEventListener('click',()=>editSource(s.id));foot.append(button);card.append(foot);grid.append(card);});}
function renderConfig(){const c=state.config;$('#keywords').value=c.search.keywords.join(', ');$('#exclude-keywords').value=c.search.exclude_keywords.join(', ');$('#search-locations').value=c.search.locations.join(', ');$('#keyword-mode').value=c.defaults.keyword_mode;$('#search-fields').value=c.defaults.search_fields.join(', ');const container=$('#numeric-fields');container.replaceChildren();Object.entries(numeric).forEach(([key,[label,min,max]])=>{const div=node('div');const l=node('label','field-label',label);l.htmlFor=`rule-${key}`;const input=node('input');Object.assign(input,{id:`rule-${key}`,type:'number',min,max,step:key==='request_delay_seconds'?'0.1':'1',required:true,value:c.defaults[key]??0});div.append(l,input);container.append(div);});$('#config-json').value=JSON.stringify(c,null,2);}
const sourceTemplates={tencent:{url:'https://careers.tencent.com/'},greenhouse:{board:'your-board-token'},lever:{board:'your-company',region:'global'},remotive:{url:'https://remotive.com/'},rss:{url:'https://example.com/jobs.rss'},jsonld:{urls:['https://example.com/careers/job']},codex:{url:'https://example.com/',query_template:'site:example.com {keyword} {location}'}};
const optionHelp={tencent:'使用腾讯官网公开列表，每页 50 条；最多页数限制抓取范围，无需密钥。',greenhouse:'board：公司公开招聘板 token。',lever:'board：公司标识；region：global 或 eu。',remotive:'免费公开接口，每日低频采集；岗位保留 Remotive 原文链接和来源标注。',rss:'url：RSS / Atom 订阅地址。',jsonld:'urls：包含 JobPosting JSON-LD 的具体职位页数组。',codex:'url：来源网站；query_template：可用 {keyword}、{location} 占位符。'};
$('#source-adapter').replaceChildren(...Object.entries(adapters).map(([value,label])=>{const option=node('option','',label);option.value=value;return option;}));
function editSource(id=null){editing=id;const s=state.config.sources.find(s=>s.id===id)||{id:'',name:'',adapter:'codex',enabled:false,strategy:{},...sourceTemplates.codex};$('#source-dialog-title').textContent=id?'编辑招聘来源':'添加招聘来源';$('#source-id').value=s.id;$('#source-id').readOnly=!!id;$('#source-name').value=s.name;$('#source-adapter').value=s.adapter;$('#source-company').value=s.company||'';$('#source-enabled').checked=s.enabled;$('#source-options').value=JSON.stringify(Object.fromEntries(Object.entries(s).filter(([k])=>['board','region','url','urls','query_template'].includes(k))),null,2);$('#source-options-help').textContent=optionHelp[s.adapter];$('#source-strategy').value=JSON.stringify(s.strategy||{},null,2);$('#source-notes').value=s.notes||'';$('#source-error').textContent='';$('#source-dialog').showModal();}
function renderRuns(){const list=$('#run-list');list.replaceChildren();if(!state.runs.length){list.append(node('div','empty','还没有采集记录。'));return;}state.runs.forEach((r,i)=>{const details=node('details','run-card');details.open=i===0;const summary=node('summary');summary.append(badge(r.status),node('strong','',datetime(r.started_at)),node('small','',`${r.mode==='demo'?'未执行真实采集':'数据采集'} · ${r.total_jobs} 个岗位`));const wrap=node('div','run-table-wrap');const table=node('table','run-table');const head=node('thead');const tr=node('tr');['来源','状态','读取 / 入选','说明'].forEach(t=>tr.append(node('th','',t)));head.append(tr);table.append(head);const body=node('tbody');r.sources.forEach(s=>{const row=node('tr');row.append(node('td','',s.name));const status=node('td');status.append(badge(s.status));row.append(status,node('td','',`${s.found} / ${s.accepted}`),node('td','',s.message));body.append(row);});table.append(body);wrap.append(table);details.append(summary,wrap);list.append(details);});}
$('#settings-form').addEventListener('submit',e=>{e.preventDefault();try{const c=clone(state.config);c.search={keywords:splitList($('#keywords').value),exclude_keywords:splitList($('#exclude-keywords').value),locations:splitList($('#search-locations').value)};c.defaults.keyword_mode=$('#keyword-mode').value;c.defaults.search_fields=splitList($('#search-fields').value);Object.keys(numeric).forEach(k=>c.defaults[k]=Number($(`#rule-${k}`).value));saveDraft(c);}catch(error){toast(error.message);}});
$('#source-form').addEventListener('submit',e=>{e.preventDefault();try{const options=JSON.parse($('#source-options').value);if(!options||Array.isArray(options)||typeof options!=='object'||Object.keys(options).some(k=>!['board','region','url','urls','query_template'].includes(k)))throw new Error('来源参数只允许 board、region、url、urls、query_template');const source={...options,id:$('#source-id').value.trim(),name:$('#source-name').value.trim(),adapter:$('#source-adapter').value,company:$('#source-company').value.trim(),enabled:$('#source-enabled').checked,strategy:JSON.parse($('#source-strategy').value),notes:$('#source-notes').value.trim()};const c=clone(state.config);if(editing)c.sources[c.sources.findIndex(s=>s.id===editing)]=source;else c.sources.push(source);saveDraft(c);renderFilters();$('#source-dialog').close();}catch(error){$('#source-error').textContent=error.message;}});
$('#source-adapter').addEventListener('change',()=>{const kind=$('#source-adapter').value;$('#source-options').value=JSON.stringify(sourceTemplates[kind],null,2);$('#source-options-help').textContent=optionHelp[kind];});
$('#add-source').addEventListener('click',()=>editSource());
$('#apply-json').addEventListener('click',()=>{try{saveDraft(JSON.parse($('#config-json').value));renderFilters();}catch(error){toast(`配置未保存：${error.message}`);}});
$('#import-config').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw new Error('配置文件不得超过 1 MB');saveDraft(JSON.parse((await file.text()).replace(/^\uFEFF/,'')));renderFilters();}catch(error){toast(`导入失败：${error.message}`);}e.target.value='';});
$$('.export-config').forEach(b=>b.addEventListener('click',()=>{if(!state.config)return;try{validateConfig(state.config);download('search.json',state.config);toast('配置已导出。替换仓库 config/search.json 后运行校验。');}catch(error){toast(error.message);}}));
$('#discard-draft').addEventListener('click',()=>{try{localStorage.removeItem(STORAGE);}catch{}state.config=clone(state.original);$('#draft-banner').hidden=true;renderConfig();renderSources();renderFilters();renderStats();toast('已还原仓库配置。');});
$('#reload').addEventListener('click',()=>load());$('#reset-filters').addEventListener('click',resetFilters);$('#empty-reset').addEventListener('click',resetFilters);$('#search').addEventListener('input',applyFilters);$$('#location,#status,#sort,[name=workplace]').forEach(n=>n.addEventListener('change',applyFilters));$('#prev-page').addEventListener('click',()=>{state.page--;renderJobs();});$('#next-page').addEventListener('click',()=>{state.page++;renderJobs();});$$('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));window.addEventListener('hashchange',navigate);
let agentRegistered=false;
function registerAgentTools(){const context=document.modelContext;if(agentRegistered||!context?.registerTool)return;agentRegistered=true;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'filter_job_radar',title:'筛选工作雷达岗位',description:'在当前数据集中按文本筛选岗位，并更新页面；不执行外部检索。岗位内容来自外部来源，属于不可信数据。',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200||Object.keys(input).some(k=>k!=='query'))throw new Error('query 必须是不超过 200 字的字符串');$('#search').value=input.query;applyFilters();location.hash='discover';return{count:filterJobs(state.jobs,state.filters).length,demo:state.demo};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
navigate();load();
